let selected = 'ssd';
let activeTab = 'overview';
let exportOpen = false;
const comparisons = new Map();
const $ = id => document.getElementById(id);
const current = () => devices.find(d => d.id === selected);
function renderList() {
  const query = $('search').value.toLocaleLowerCase('ru').trim();
  const visible = devices.filter(d => `${d.name} ${d.type} ${d.status}`.toLocaleLowerCase('ru').includes(query));
  $('device-list').innerHTML = visible.length ? visible.map(d => `<button class="device" data-device="${d.id}" aria-pressed="${selected === d.id}"><span class="device-icon" aria-hidden="true">${d.icon}</span><span><strong>${d.name}</strong><small class="${d.tone}">${d.status}</small><small>${d.type}</small></span></button>`).join('') : '<p class="empty" role="status">Совпадений нет. Попробуйте другое название.</p>';
}
function overview(d) {
  return `<section class="diagnosis ${d.tone}"><div class="kicker">${d.id === 'phone' ? 'ПОСЛЕДНЕЕ НАБЛЮДЕНИЕ' : 'ЧТО ИЗВЕСТНО'}</div><h2>${d.headline}</h2><p>${d.fact}</p></section>
  <section class="section"><div class="section-heading"><h3>Путь подключения</h3><button class="text-link" data-action="details">Технические сведения</button></div><div class="chain" aria-label="Путь подключения">${d.path.map((p,i) => `${i ? '<span class="arrow" aria-hidden="true">→</span>' : ''}<div class="chain-node"><strong>${p[0]}</strong><small>${p[1]}</small></div>`).join('')}</div><p class="footnote">Логический путь из примера. Расположение разъёма на корпусе не определено.</p></section>
  <section class="section"><div class="metric-grid"><div><div class="metric-label">${d.id === 'phone' ? 'Последний снимок' : 'Режим соединения'}</div><div class="metric-value">${d.speed}</div><div class="muted">${d.mode}</div></div><div><div class="metric-label">Возможности устройства</div><div class="metric-value">${d.capability}</div><div class="muted">${d.capNote}</div></div></div><p class="footnote">Режим USB не равен скорости копирования. Тест чтения здесь не выполнялся.</p></section>
  <section class="section"><h3>${d.id === 'ssd' ? 'Возможная причина' : 'Как это понимать'}</h3><p class="muted">${d.reason}</p></section>
  <section class="next-step"><span class="step-number" aria-hidden="true">→</span><div><h3>${d.next}</h3><p>${d.nextText}</p></div>${d.id === 'ssd' || d.id === 'keyboard' ? '<button class="button" data-action="compare">Сравнить подключение →</button>' : '<button class="button secondary" data-action="journal">Посмотреть журнал</button>'}</section>`;
}
function comparison(d) {
  if (d.id !== 'ssd' && d.id !== 'keyboard') return `<h2>Сравнение подключений</h2><p class="muted">${d.name}</p><div class="notice">${d.id === 'phone' ? 'Устройство отсутствует. Для сравнения нужен новый снимок подключённого устройства и подтверждение его идентичности.' : 'Не хватает сведений, чтобы достоверно сравнить скорость. Недоступное поле не считаем ухудшением.'}</div><button class="button secondary" data-action="overview">К обзору</button>`;
  const done = comparisons.get(d.id);
  if (!done) return `<span class="state-pill">Демонстрационный сценарий</span><h2 style="margin-top:16px">Одно изменение — понятное сравнение</h2><p class="muted">${d.name} · первый снимок уже выбран</p><ol class="instructions"><li>Сохраните исходный путь и режим подключения.</li><li>В реальной проверке подключите устройство напрямую к другому порту. Оставьте тот же кабель.</li><li>Подтвердите устройство и сравните второй снимок.</li></ol><div class="notice">Здесь второй снимок заранее подготовлен. Нажатие кнопки не читает USB, не меняет настройки и не проверяет ваш компьютер.</div><label class="confirm"><input id="identity-confirm" type="checkbox">Сравниваем то же устройство</label><button class="button" id="simulate" disabled>Показать второй пример</button>`;
  return `<span class="state-pill">Два примера · ${d.name}</span><h2 style="margin-top:16px">${d.id === 'ssd' ? 'Второй снимок показывает более быстрый режим' : 'Режим остался прежним — это ожидаемо'}</h2><table><thead><tr><th scope="col">Параметр</th><th scope="col">До · пример A</th><th scope="col">После · пример B</th></tr></thead><tbody><tr><td>Подключение</td><td>${d.id === 'ssd' ? 'Через внешний хаб' : 'Корневой хаб · порт 2'}</td><td>Напрямую · порт 4</td></tr><tr><td>Режим USB</td><td>${d.speed}</td><td class="improved">${d.id === 'ssd' ? '5 Гбит/с · SuperSpeed' : d.speed}</td></tr><tr><td>Состояние Windows</td><td>Работает</td><td>Работает</td></tr><tr><td>Идентичность</td><td colspan="2">Один ID синтетической фикстуры; реальное сопоставление не выполнялось</td></tr></tbody></table><div class="notice">${d.id === 'ssd' ? 'Что следует из примера: в другом пути устройство работает в SuperSpeed. Это не доказывает неисправность хаба или кабеля и не измеряет скорость копирования.' : 'Full-Speed сам по себе не является проблемой клавиатуры. Смена порта не обязана повышать скорость.'}</div><div class="actions"><button class="button secondary" data-action="reset-comparison">Начать сравнение заново</button><button class="text-link" data-action="journal">Открыть журнал примера</button></div>`;
}
function journal(d) {
  const entries = comparisons.get(d.id) ? [['14:33','Открыт второй пример','Синтетический снимок B; это действие в прототипе, а не USB-событие'],...d.events] : d.events;
  return `<h2>Журнал устройства</h2><p class="muted">${d.name} · вымышленные события только этого устройства</p><div class="notice">Реальное наблюдение не запущено. В приложении журнал будет содержать события только за время его работы; отсутствие событий не доказывает стабильность.</div><ol class="journal">${entries.map(e => `<li><time>${e[0]}</time><div>${e[1]}<small>${e[2]}</small></div></li>`).join('')}</ol>`;
}
function details(d) {
  return `<h2>Сведения без догадок</h2><p class="muted">${d.name} · пояснения рядом с исходными полями</p><details open><summary>Windows и драйвер</summary><table><tbody><tr><td>Состояние</td><td>${d.windows}</td></tr><tr><td>Драйвер</td><td>${d.driver}</td></tr></tbody></table><p>Код проблемы 0 означает отсутствие сообщённой Windows проблемы в снимке. Это не проверка физического состояния устройства.</p></details><details><summary>Откуда взялся режим соединения</summary><pre>${d.details}</pre><p>Режим и возможности — разные поля. bcdUSB описывает версию спецификации и сам по себе не доказывает максимальную скорость. При противоречивых или неполных данных диагноз должен быть «неизвестно».</p></details><details><summary>Что означают дескрипторы</summary><p><code>idVendor / idProduct</code> — идентификаторы производителя и продукта. Они не гарантируют уникальность экземпляра.</p><p><code>bDeviceClass</code> — класс устройства. У составного устройства класс может задаваться для каждого интерфейса отдельно.</p><p><code>bMaxPower</code> — заявленное потребление в конфигурации. Это не измерение тока; единицы зависят от применимой версии USB.</p><p><code>iSerialNumber</code> — индекс строки серийного номера, а не сам серийник. Отсутствие строки затрудняет сопоставление после смены порта.</p></details><details><summary>О чём этот снимок не говорит</summary><p>Качество сигнала, фактические ток и напряжение, исправность кабеля и точная причина отключения не измерены. USB-C — форма разъёма, а не обещание скорости. USB4 и Thunderbolt требуют отдельной модели данных.</p></details>`;
}
function report(d) {
  return {schema_version:1,demo:true,source:'synthetic_fixture',device:{id:d.id,name:d.name,serial_number:'[скрыто]',computer_name:'[скрыто]',personal_paths:'[скрыто]',present:d.id !== 'phone',connection_speed:d.id === 'unknown' ? null : d.speed,speed_is_historical:d.id === 'phone',windows_state:d.windows},observations:d.fact,hypothesis:d.reason,comparison_example_opened:!!comparisons.get(d.id),limitations:['Не измерение оборудования','Не содержит реальных серийников или персональных путей']};
}
function render() {
  const priorFocus = document.activeElement;
  const focusInside = $('content').contains(priorFocus);
  const d = current();
  $('device-title').textContent = d.name;
  $('device-subtitle').textContent = `${d.type} · ${d.status}`;
  document.querySelectorAll('[data-tab]').forEach(b => {if(b.dataset.tab === activeTab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  $('export').setAttribute('aria-expanded',String(exportOpen));
  const preview = exportOpen ? `<section class="export-preview"><h3>Обезличенный пример отчёта</h3><p class="muted">Только ${d.name}. Маркер demo: true. Серийник, имя компьютера и персональные пути скрыты.</p><details><summary>Посмотреть JSON перед сохранением</summary><pre id="report-preview"></pre></details><div class="actions"><button class="button" data-action="download">Скачать пример JSON</button><button class="text-link" data-action="close-export">Закрыть</button></div></section>` : '';
  $('content').innerHTML = preview + ({overview,compare:comparison,journal,details}[activeTab])(d);
  if(exportOpen)$('report-preview').textContent = JSON.stringify(report(d),null,2);
  // Content actions replace their own panel; retain a meaningful keyboard focus.
  if(focusInside){const target=$('content').querySelector('h2, h3');if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}}
}
function switchTab(tab) {activeTab=tab;render();$('announcement').textContent=`Раздел ${document.querySelector('[aria-current="page"]').textContent}, ${current().name}`;}
$('search').addEventListener('input',renderList);
document.addEventListener('click',event => {
  const button = event.target.closest('button');if(!button)return;
  if(button.dataset.device){selected=button.dataset.device;exportOpen=false;renderList();render();$('announcement').textContent=`Выбрано: ${current().name}`;return;}
  if(button.dataset.tab){switchTab(button.dataset.tab);return;}
  if(button.id === 'export'){exportOpen=!exportOpen;render();return;}
  if(button.id === 'simulate'){comparisons.set(selected,true);render();$('announcement').textContent='Показан второй синтетический снимок';return;}
  const action=button.dataset.action;
  if(['overview','compare','journal','details'].includes(action)){switchTab(action);return;}
  if(action==='reset-comparison'){comparisons.delete(selected);render();return;}
  if(action==='close-export'){exportOpen=false;render();return;}
  if(action==='download'){
    const blob=new Blob([JSON.stringify(report(current()),null,2)],{type:'application/json;charset=utf-8'});
    const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`usb-doctor-demo-${selected}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('announcement').textContent='Скачан обезличенный демонстрационный отчёт';
  }
});
document.addEventListener('change',event=>{if(event.target.id==='identity-confirm')$('simulate').disabled=!event.target.checked;});
renderList();render();
